template<typename IteratorA, typename IteratorB>
class ReverseIterator {};

template<typename ItA, typename ItB>
bool operator>(
    const ReverseIterator<ItA>& lhs,
    const ReverseIterator<ItB>& rhs)
{
    // Custom logic for reverse iterators comparison
    // Compares underlying base iterators
    return rhs.base() > lhs.base();
}

